  "settings.whatsapp.retentionForeverWarning": "À 0, ce panneau ne supprime jamais rien de WhatsApp. Le texte des conversations, les photos et les documents envoyés par l'abonné sont conservés indéfiniment — et ce sont les seules données du système sans échéance : la télémétrie, les événements de l'ERP, le provisionnement et la piste d'audit en ont tous une. Fixer une échéance est ce qui borne les données personnelles que vous gardez, et la croissance du disque.",
